/* eslint-disable @typescript-eslint/no-unused-vars */
import { useCallback, useEffect, useMemo, useState } from "react";
import type { JSX } from "react";
import { defaultAccountSelection, type Account, type ActivityLog, type Article, type Brand, type DashboardStats, type ImageAsset, type KeywordItem, type KeywordTemplate, type Platform, type PublishJob, type PublishPlan } from "@publisher/domain";
import type { AccountManagementRow, BatchGenerationInput, ContentStudioTaskView } from "../shared/api";
import { DeepSeekSettingsPage } from "./DeepSeekSettingsPage";
import { PlansPageV031 } from "./PlansPageV031";
import { QueuePageV031 } from "./QueuePageV031";
import { DouyinVerificationWizard } from "./DouyinVerificationWizard";
import { VideoAssetCenter } from "./VideoAssetCenter";
import { WeChatVerificationWizard } from "./WeChatVerificationWizard";
import { AIContentStudio } from "./AIContentStudio";
import { QualityGatePage } from "./QualityGatePage";
import { PlatformRulesPage } from "./PlatformRulesPage";
import { PlatformConnectionCenter } from "./PlatformConnectionCenter";
import { disconnectFeedbackMessage } from "./platform-connection-ui";
import { ImageLibraryPage } from "./ImageLibraryPage";
import { PlatformSelfTestCenter } from "./PlatformSelfTestCenter";
import { EnterpriseProfileManager } from "./EnterpriseProfileManager";
import { beginPostLoginHeartbeat, runCheckLoginWithHeartbeats } from "./session-heartbeat";
import { V11AccountsCenter, V11AdvancedSettings, V11ArticleLibrary, V11ContentProduction, V11Dashboard, V11ImageLibrary, V11Preferences, V11PublishCenter, V11Statistics } from "./V11Workspace";
import { normalNavigation, type V11NavigationTarget } from "./v11-ui-model";

type Route = V11NavigationTarget;

const navGroups: { title: string; items: { route: Route; label: string; icon: string }[] }[] = [{ title: "运营工作台", items: normalNavigation }];

const routeLabels = new Map<Route, string>([...navGroups.flatMap((group) => group.items.map((item) => [item.route, item.label] as const)), ["preferences", "设置"], ["advanced", "高级设置"], ["studio", "内容生产高级设置"], ["quality", "高级审核规则"], ["quality-rules", "平台内容规则"], ["batch", "批量生成"], ["keywords", "关键词扩展"], ["ai-tasks", "内容生产记录"], ["assets", "视频素材"], ["images-advanced", "图片高级标签"], ["brand", "企业资料"], ["knowledge", "企业知识库"], ["platforms", "平台能力"], ["self-test", "平台自测"], ["plans", "发布计划"], ["queue", "发布任务与技术诊断"], ["logs", "运行日志"], ["backups", "数据备份"], ["settings", "AI 与模型设置"], ["placeholder", "模块准备中"]]);
const cities = ["南京", "苏州", "无锡", "常州", "南通", "扬州", "镇江", "泰州", "盐城", "徐州", "淮安", "连云港", "宿迁"];

export function App(): JSX.Element {
  const [route, setRoute] = useState<Route>("dashboard");
  const [refreshKey, setRefreshKey] = useState(0);
  const refresh = (): void => setRefreshKey((value) => value + 1);
  return <Layout route={route} onNavigate={setRoute}>
    {route === "dashboard" && <V11Dashboard refreshKey={refreshKey} onNavigate={setRoute} />}
    {route === "production" && <V11ContentProduction refresh={refresh} onNavigate={setRoute} />}
    {route === "articles" && <V11ArticleLibrary refresh={refresh} refreshKey={refreshKey} onNavigate={setRoute} />}
    {route === "images" && <V11ImageLibrary refresh={refresh} refreshKey={refreshKey} />}
    {route === "accounts" && <V11AccountsCenter refresh={refresh} refreshKey={refreshKey} onNavigate={setRoute} />}
    {route === "publishing" && <V11PublishCenter refresh={refresh} refreshKey={refreshKey} onNavigate={setRoute} />}
    {route === "statistics" && <V11Statistics refreshKey={refreshKey} />}
    {route === "preferences" && <V11Preferences />}
    {route === "advanced" && <V11AdvancedSettings onNavigate={setRoute} />}
    {route === "studio" && <AIContentStudio refresh={refresh} />}
    {route === "quality" && <QualityGatePage refresh={refresh} />}
    {route === "quality-rules" && <PlatformRulesPage />}
    {route === "batch" && <BatchPage refresh={refresh} />}
    {route === "keywords" && <KeywordsPage />}
    {route === "ai-tasks" && <AiTasksPage />}
    {route === "assets" && <VideoAssetCenter refresh={refresh} />}
    {route === "images-advanced" && <ImageLibraryPage refresh={refresh} />}
    {(route === "brand" || route === "knowledge") && <EnterpriseProfileManager initialView={route === "knowledge" ? "knowledge" : "profile"} refresh={refresh} onNavigate={setRoute} />}
    {route === "platforms" && <PlatformConnectionCenter refresh={refresh} onNavigate={(nextRoute) => setRoute(nextRoute)} />}
    {route === "self-test" && <PlatformSelfTestCenter onNavigate={setRoute} />}
    {route === "plans" && <PlansPageV031 refresh={refresh} />}
    {route === "queue" && <QueuePageV031 refresh={refresh} />}
    {route === "statistics" && <StatisticsPage />}
    {route === "logs" && <LogsPage />}
    {route === "backups" && <BackupsPage />}
    {route === "settings" && <DeepSeekSettingsPage />}
    {route === "placeholder" && <EmptyState title="模块准备中" description="该扩展入口已纳入工作台导航，后续版本会复用现有数据与任务基础继续完善。" />}
  </Layout>;
}

function Layout({ route, onNavigate, children }: { route: Route; onNavigate: (route: Route) => void; children: React.ReactNode }): JSX.Element {
  const current = routeLabels.get(route) ?? "首页";
  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand-lockup"><div className="brand-mark">矩</div><div><strong>矩阵发布</strong><span>内容运营工作台</span></div></div>
      <div className="workspace-switch"><span className="workspace-dot" /> 内容运营 <span className="chevron">⌄</span></div>
      <nav>{navGroups.map((group) => <div className="nav-group" key={group.title}><div className="nav-caption">{group.title}</div>{group.items.map((item) => <button className={`nav-item ${item.route === route ? "active" : ""}`} key={item.route} onClick={() => onNavigate(item.route)}><span className="nav-icon">{item.icon}</span>{item.label}</button>)}</div>)}</nav>
      <div className="sidebar-footer"><button className={`nav-item ${route === "preferences" ? "active" : ""}`} onClick={() => onNavigate("preferences")}><span className="nav-icon">⚙</span>设置</button><button className={`nav-item ${route === "advanced" ? "active" : ""}`} onClick={() => onNavigate("advanced")}><span className="nav-icon">⌘</span>高级功能</button></div>
    </aside>
    <main className="main-area"><header className="topbar"><div><div className="breadcrumb">内容运营 <span>/</span> {current}</div><h1>{current}</h1></div><div className="top-actions"><button className="icon-button" title="通知">♢<span className="notification-dot" /></button><div className="avatar">运</div></div></header><section className="content-area">{children}</section></main>
  </div>;
}

function PageTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }): JSX.Element {
  return <div className="page-title"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</div>;
}

function StatCard({ label, value, hint, tone = "blue", icon }: { label: string; value: string | number; hint: string; tone?: string; icon: string }): JSX.Element {
  return <div className={`stat-card ${tone}`}><div className="stat-icon">{icon}</div><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-hint">{hint}</div></div>;
}

function DashboardPage({ refreshKey, onNavigate }: { refreshKey: number; onNavigate: (route: Route) => void }): JSX.Element {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [jobs, setJobs] = useState<PublishJob[]>([]);
  useEffect(() => { void Promise.all([window.publisherAPI.dashboard.get(), window.publisherAPI.jobs.list()]).then(([nextStats, nextJobs]) => { setStats(nextStats); setJobs(nextJobs); }); }, [refreshKey]);
  const value = stats ?? { publishedToday: 0, pendingJobs: 0, failedJobs: 0, runningJobs: 0, totalAccounts: 0, onlineAccounts: 0, expiredAccounts: 0, availableArticles: 0, generatedToday: 0, estimatedStockDays: 0, activeAiTasks: 0, benchmarkArticles: 0, productionArticles: 0 };
  return <><PageTitle eyebrow="运营总览" title="今天，开始让内容持续运转" description="掌握内容库存、AI 生产和发布队列的实时状态。" action={<button className="primary-button" onClick={() => onNavigate("batch")}>＋ 创建内容</button>} /><div className="stat-grid"><StatCard label="今日已发布" value={value.publishedToday} hint={`${value.runningJobs} 个任务正在运行`} icon="↗" /><StatCard label="待发布任务" value={value.pendingJobs} hint="来自持久化队列" tone="purple" icon="◷" /><StatCard label="可用文章库存" value={value.availableArticles} hint={`预计可用 ${value.estimatedStockDays} 天`} tone="green" icon="▤" /><StatCard label="在线账号" value={`${value.onlineAccounts} / ${value.totalAccounts}`} hint={`${value.expiredAccounts} 个需要检查登录`} tone="orange" icon="◎" /></div><div className="dashboard-grid"><section className="panel timeline-panel"><div className="panel-heading"><div><h3>今日发布计划</h3><span>持久化任务时间轴</span></div><button className="text-button" onClick={() => onNavigate("queue")}>查看队列 →</button></div>{jobs.length === 0 ? <EmptyState compact title="今天还没有排期任务" description="在发布计划中选择文章和账号后生成任务。" /> : <div className="timeline-list">{jobs.slice(0, 5).map((job) => <div className="timeline-item" key={job.id}><div className="timeline-time">{new Date(job.scheduledAt).toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" })}</div><div className={`timeline-dot ${job.status.toLowerCase()}`} /><div className="timeline-content"><strong>{job.platformKey} · {job.status}</strong><span>{job.id.slice(0, 8)} · 账号 {job.accountId.slice(0, 8)}</span></div><StatusPill status={job.status} /></div>)}</div>}</section><section className="panel health-panel"><div className="panel-heading"><div><h3>系统运行状态</h3><span>本地环境与能力检查</span></div><span className="status-chip success">● 正常</span></div><div className="health-row"><span>SQLite 持久化</span><b>已启用</b></div><div className="health-row"><span>Mock AI Provider</span><b>可用</b></div><div className="health-row"><span>TestPlatform Adapter</span><b>可用</b></div><div className="health-row"><span>真实平台 Adapter</span><b className="muted">未接入</b></div><div className="stock-alert"><span>♢</span><div><strong>{value.availableArticles < 10 ? "内容库存偏低" : "内容库存充足"}</strong><p>{value.availableArticles < 10 ? "前往批量生成补充可用文章。" : "当前库存可以支持持续发布。"}</p></div></div></section></div></>;
}

function BatchPage({ refresh }: { refresh: () => void }): JSX.Element {
  const [brands, setBrands] = useState<Brand[]>([]);
  const [templates, setTemplates] = useState<KeywordTemplate[]>([]);
  const [brandId, setBrandId] = useState("");
  const [selectedTemplates, setSelectedTemplates] = useState<string[]>([]);
  const [selectedCities, setSelectedCities] = useState<string[]>(cities.slice(0, 3));
  const [articleType, setArticleType] = useState("科普");
  const [perKeyword, setPerKeyword] = useState(1);
  const [concurrency, setConcurrency] = useState(2);
  const [autoCover, setAutoCover] = useState(true);
  const [taskId, setTaskId] = useState<string | null>(null);
  const [task, setTask] = useState<{ total: number; completed: number; success: number; failed: number; status: string } | null>(null);
  useEffect(() => { void window.publisherAPI.brands.list().then((items) => { setBrands(items); if (items[0]) setBrandId(items[0].id); }); }, []);
  useEffect(() => { if (brandId) void window.publisherAPI.keywords.templates(brandId).then((items) => { setTemplates(items); setSelectedTemplates(items.filter((item) => item.enabled).map((item) => item.id)); }); }, [brandId]);
  useEffect(() => { if (!taskId) return; const timer = window.setInterval(() => { void window.publisherAPI.ai.task(taskId).then((next) => { if (next) setTask({ total: next.total, completed: next.completed, success: next.success, failed: next.failed, status: next.status }); }); }, 700); return () => window.clearInterval(timer); }, [taskId]);
  const estimated = selectedCities.length * Math.max(1, selectedTemplates.length) * perKeyword;
  const start = async (): Promise<void> => { if (!brandId || selectedCities.length === 0 || selectedTemplates.length === 0) return; const input: BatchGenerationInput = { brandId, cities: selectedCities, templateIds: selectedTemplates, articleType, perKeyword, concurrency, minWords: 500, maxWords: 900, autoCover, includeSummary: true, includeTags: true, includeSeoKeywords: true }; const id = await window.publisherAPI.ai.startBatch(input); setTaskId(id); setTask({ total: Math.min(1000, estimated), completed: 0, success: 0, failed: 0, status: "running" }); refresh(); };
  return <><PageTitle eyebrow="AI 创作 / 批量生成" title="批量生成内容" description="把品牌资料、城市和关键词组合成可审计的内容生产任务。" action={<span className="draft-label">草稿自动保存</span>} /><div className="workflow-steps"><div className="step active"><b>01</b><span>选择范围</span></div><div className="step-line" /><div className="step"><b>02</b><span>生成配置</span></div><div className="step-line" /><div className="step"><b>03</b><span>执行任务</span></div></div><div className="form-layout"><section className="panel form-panel"><div className="panel-heading"><div><h3>内容生产范围</h3><span>生成前先确认业务边界</span></div></div><label>品牌<select value={brandId} onChange={(event) => setBrandId(event.target.value)}>{brands.map((brand) => <option value={brand.id} key={brand.id}>{brand.name} · {brand.companyName}</option>)}</select></label><label>目标城市<div className="chip-select">{cities.map((city) => <button className={`choice-chip ${selectedCities.includes(city) ? "selected" : ""}`} key={city} onClick={() => setSelectedCities((current) => current.includes(city) ? current.filter((item) => item !== city) : [...current, city])}>{city}</button>)}</div></label><label>关键词模板<div className="template-list">{templates.map((template) => <label className="check-row" key={template.id}><input type="checkbox" checked={selectedTemplates.includes(template.id)} onChange={() => setSelectedTemplates((current) => current.includes(template.id) ? current.filter((id) => id !== template.id) : [...current, template.id])} /><span>{template.template}</span><em>{template.category}</em></label>)}</div></label></section><section className="panel form-panel"><div className="panel-heading"><div><h3>生成配置</h3><span>支持有限并发，任务进度写入 SQLite</span></div></div><label>文章类型<select value={articleType} onChange={(event) => setArticleType(event.target.value)}>{["科普", "推荐", "问答", "避坑", "案例", "服务介绍", "流程", "城市本地化"].map((item) => <option key={item}>{item}</option>)}</select></label><div className="two-fields"><label>每关键词生成<input type="number" min="1" max="10" value={perKeyword} onChange={(event) => setPerKeyword(Number(event.target.value))} /></label><label>AI 并发<input type="number" min="1" max="20" value={concurrency} onChange={(event) => setConcurrency(Number(event.target.value))} /></label></div><div className="toggle-row"><div><strong>自动生成模板封面</strong><span>生成 SVG 封面并写入本地素材记录</span></div><button className={`toggle ${autoCover ? "on" : ""}`} onClick={() => setAutoCover((value) => !value)}><span /></button></div><div className="estimate-box"><span>预计生成</span><strong>{Math.min(1000, estimated)} <small>篇文章</small></strong><p>{selectedCities.length} 个城市 × {selectedTemplates.length} 个模板 × {perKeyword} 次（单任务最多 1000 篇）</p></div><button className="primary-button wide" onClick={() => void start()} disabled={!brandId || !selectedTemplates.length || !selectedCities.length || task?.status === "running"}>{task?.status === "running" ? "任务执行中…" : "开始生成"}</button>{task?.status === "running" && taskId && <button className="secondary-button wide" onClick={() => void window.publisherAPI.ai.cancel(taskId)}>取消任务</button>}</section></div>{task && <section className="panel task-progress"><div className="progress-header"><div><h3>当前 AI 任务</h3><span>{task.status === "running" ? "正在写入文章库" : task.status === "cancelled" ? "任务已取消，可从已完成进度继续" : "任务已完成"}</span></div><strong>{task.completed} / {task.total}</strong></div><div className="progress-track"><span style={{ width: `${task.total ? (task.completed / task.total) * 100 : 0}%` }} /></div><div className="progress-meta"><span>成功 {task.success}</span><span>失败 {task.failed}</span><span>状态 {task.status}</span></div></section>}</>;
}

function KeywordsPage(): JSX.Element {
  const [brands, setBrands] = useState<Brand[]>([]); const [brandId, setBrandId] = useState(""); const [templates, setTemplates] = useState<KeywordTemplate[]>([]); const [items, setItems] = useState<KeywordItem[]>([]); const [cityText, setCityText] = useState(cities.join("、")); const [newTemplate, setNewTemplate] = useState(""); const [message, setMessage] = useState("");
  const load = (id: string): void => { setBrandId(id); void Promise.all([window.publisherAPI.keywords.templates(id), window.publisherAPI.keywords.items(id)]).then(([nextTemplates, nextItems]) => { setTemplates(nextTemplates); setItems(nextItems); }); };
  useEffect(() => { void window.publisherAPI.brands.list().then((list) => { setBrands(list); if (list[0]) load(list[0].id); }); }, []);
  const expand = async (): Promise<void> => { const result = await window.publisherAPI.keywords.expand({ brandId, cities: cityText.split(/[、,，\s]+/).filter(Boolean) }); setMessage(`已新增 ${result.count} 个关键词${result.duplicates ? `，去重 ${result.duplicates} 个` : ""}`); void window.publisherAPI.keywords.items(brandId).then(setItems); };
  return <><PageTitle eyebrow="AI 创作 / 关键词扩展" title="城市关键词扩展" description="用模板批量组合城市关键词，自动去重并写入关键词库。" action={<button className="primary-button" onClick={() => void expand()}>生成关键词</button>} /><div className="two-column"><section className="panel form-panel"><div className="panel-heading"><div><h3>组合设置</h3><span>支持 {`{城市}`} 占位符</span></div></div><label>品牌<select value={brandId} onChange={(event) => load(event.target.value)}>{brands.map((brand) => <option key={brand.id} value={brand.id}>{brand.name}</option>)}</select></label><label>城市列表<textarea rows={4} value={cityText} onChange={(event) => setCityText(event.target.value)} /></label><div className="inline-form"><input placeholder="新增关键词模板，例如：{城市}甲醛治理费用" value={newTemplate} onChange={(event) => setNewTemplate(event.target.value)} /><button className="secondary-button" onClick={() => { if (newTemplate.trim() && brandId) void window.publisherAPI.keywords.createTemplate({ brandId, template: newTemplate, category: "自定义" }).then(() => { setNewTemplate(""); load(brandId); }); }}>添加</button></div>{message && <div className="notice success">✓ {message}</div>}<div className="template-list compact-list">{templates.map((template) => <div className="template-row" key={template.id}><span className={`template-status ${template.enabled ? "enabled" : ""}`} /><span>{template.template}</span><em>{template.category}</em><button className="mini-button" onClick={() => void window.publisherAPI.keywords.updateTemplate(template.id, { enabled: !template.enabled }).then(() => load(brandId))}>{template.enabled ? "停用" : "启用"}</button></div>)}</div></section><section className="panel table-panel"><div className="panel-heading"><div><h3>已生成关键词</h3><span>当前共 {items.length} 条，可直接用于批量生成</span></div><div className="metric-highlight">{cityText.split(/[、,，\s]+/).filter(Boolean).length * templates.filter((item) => item.enabled).length}<small>预估组合</small></div></div>{items.length === 0 ? <EmptyState compact title="还没有关键词" description="调整城市和模板后点击生成。" /> : <div className="data-table keyword-table"><div className="table-head"><span>关键词</span><span>城市</span><span>状态</span></div>{items.slice(0, 60).map((item) => <div className="table-row" key={item.id}><strong>{item.keyword}</strong><span>{item.city}</span><StatusPill status={item.status} /></div>)}</div>}</section></div></>;
}

function ExcelImportModal({ preview, brands, onClose, onComplete }: { preview: Awaited<ReturnType<typeof window.publisherAPI.articles.importExcel>> & NonNullable<Awaited<ReturnType<typeof window.publisherAPI.articles.importExcel>>>; brands: Brand[]; onClose: () => void; onComplete: () => void }): JSX.Element {
  const [draft, setDraft] = useState(preview);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [duplicateOverrides, setDuplicateOverrides] = useState<number[]>([]);
  const setBrand = (rowNumber: number, brandId: string): void => setDraft((current) => ({ ...current, rows: current.rows.map((row) => row.rowNumber === rowNumber ? { ...row, matchedBrandId: brandId || null } : row) }));
  const confirm = async (): Promise<void> => { setBusy(true); try { const result = await window.publisherAPI.articles.confirmExcelImport(draft, duplicateOverrides); setMessage(`已导入 ${result.imported} 篇；跳过重复 ${result.skippedDuplicates} 篇；失败 ${result.failed} 行`); onComplete(); } catch (error) { setMessage(error instanceof Error ? error.message : "Excel 导入失败"); } finally { setBusy(false); } };
  const errors = draft.rows.filter((row) => row.status !== "VALID");
  return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" onClick={(event) => event.stopPropagation()}><div className="drawer-head"><div><span className="eyebrow">Excel 导入预览</span><h2>{draft.fileName}</h2></div><button className="icon-button" onClick={onClose}>×</button></div><div className="hint-box">模板版本 {draft.templateVersion} · 总行数 {draft.totalRows} · 可导入 {draft.validRows} · 重复 {draft.duplicateRows} · 错误/待匹配 {draft.errorRows}</div>{draft.warnings.length > 0 && <div className="notice">{draft.warnings.join("；")}</div>}{message && <div className="notice success">{message}</div>}<div className="log-list">{draft.rows.map((row) => <div className="log-row" key={row.rowNumber}><div><strong>第 {row.rowNumber} 行 · {row.title || "无标题"}</strong><span>{row.status} · {row.errorReason || "可导入"}</span></div>{row.status === "UNKNOWN_BRAND" && <select value={row.matchedBrandId ?? ""} onChange={(event) => setBrand(row.rowNumber, event.target.value)}><option value="">跳过该行</option>{brands.map((brand) => <option value={brand.id} key={brand.id}>{brand.name} · {brand.companyName}</option>)}</select>}{row.status === "DUPLICATE" && <label className="check-row"><input type="checkbox" checked={duplicateOverrides.includes(row.rowNumber)} onChange={(event) => setDuplicateOverrides((current) => event.target.checked ? [...current, row.rowNumber] : current.filter((item) => item !== row.rowNumber))} /><span>显式覆盖重复</span></label>}</div>)}</div>{errors.length > 0 && <button className="secondary-button" onClick={() => void window.publisherAPI.articles.exportExcelErrors(draft)}>导出错误报告</button>}<div className="drawer-footer"><button className="secondary-button" onClick={onClose}>取消</button><button className="primary-button" disabled={busy} onClick={() => void confirm()}>{busy ? "导入中…" : "确认导入"}</button></div></aside></div>;
}

function ArticlePublishModal({ article, onClose, onDone }: { article: Article; onClose: () => void; onDone: () => void }): JSX.Element {
  const [accounts, setAccounts] = useState<Account[]>([]); const [quality, setQuality] = useState<Awaited<ReturnType<typeof window.publisherAPI.quality.status>>>(null); const [accountId, setAccountId] = useState(""); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false);
  useEffect(() => { void Promise.all([window.publisherAPI.accounts.list(), window.publisherAPI.quality.status("article", article.id)]).then(([nextAccounts, nextQuality]) => { const zhihu = nextAccounts.filter((account) => account.platformKey === "zhihu" && account.loginStatus === "logged_in" && account.enabled); setAccounts(zhihu); if (zhihu[0]) setAccountId(zhihu[0].platformAccountId ?? zhihu[0].id); setQuality(nextQuality); }); }, [article.id]);
  const prepare = async (): Promise<void> => { if (!accountId) return; setBusy(true); try { const result = await window.publisherAPI.articles.preparePublish({ articleId: article.id, platformKey: "zhihu", platformAccountId: accountId, publishMode: "ASSISTED" }); setMessage(`${result.message} 任务 ${result.job.id.slice(0, 12)}，状态 ${result.job.status}`); onDone(); } catch (error) { setMessage(error instanceof Error ? error.message : "知乎准备发布失败"); } finally { setBusy(false); } };
  const approved = quality?.status === "Approved";
  return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" onClick={(event) => event.stopPropagation()}><div className="drawer-head"><div><span className="eyebrow">知乎辅助发布</span><h2>{article.title}</h2></div><button className="icon-button" onClick={onClose}>×</button></div><div className="hint-box">标题：{article.title}<br />来源：{article.source ?? "production"}<br />Quality Gate：{quality?.status ?? "读取中"}<br />平台：知乎 · 模式：BrowserAutomation / ASSISTED</div>{!approved && <div className="notice error">仅 Approved 内容可创建发布任务；当前不会打开知乎编辑器。</div>}{accounts.length === 0 && <div className="notice">没有已连接且启用的知乎账号，请先在账号中心完成官方登录。</div>}{accounts.length > 0 && <label>知乎账号<select value={accountId} onChange={(event) => setAccountId(event.target.value)}>{accounts.map((account) => <option value={account.platformAccountId ?? account.id} key={account.platformAccountId ?? account.id}>{account.name} · {account.connectionMode ?? "Manual"}</option>)}</select></label>}{message && <div className="notice success">{message}</div>}<div className="hint-box">系统会持久化 Job Queue，打开编辑器后只填充标题/正文并校验实际输入；不会点击最终发布，也不会绕过验证码或风控。</div><div className="drawer-footer"><button className="secondary-button" onClick={onClose}>取消</button><button className="primary-button" disabled={busy || !approved || !accountId} onClick={() => void prepare()}>{busy ? "准备中…" : "创建任务并打开编辑器"}</button></div></aside></div>;
}

function SimpleArticlePublishModal({ article, onClose, onDone, onNavigate }: { article: Article; onClose: () => void; onDone: () => void; onNavigate: (route: Route) => void }): JSX.Element {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [platforms, setPlatforms] = useState<Platform[]>([]);
  const [quality, setQuality] = useState<Awaited<ReturnType<typeof window.publisherAPI.quality.status>>>(null);
  const [platformKey, setPlatformKey] = useState("");
  const [accountId, setAccountId] = useState("");
  const [images, setImages] = useState<ImageAsset[]>([]);
  const [selectedImage, setSelectedImage] = useState<ImageAsset | null>(null);
  const [imageMode, setImageMode] = useState<"random" | "manual" | "none">("random");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const availableAccounts = useMemo(() => accounts.filter((account) => account.platformKey === platformKey), [accounts, platformKey]);
  const platformName = platforms.find((platform) => platform.platformKey === platformKey)?.displayName ?? platformKey;
  useEffect(() => {
    void Promise.all([window.publisherAPI.accounts.list(), window.publisherAPI.platforms.list(), window.publisherAPI.quality.status("article", article.id), window.publisherAPI.imageAssets.list({ brandId: article.brandId, enabledOnly: true })]).then(([nextAccounts, nextPlatforms, nextQuality, nextImages]) => {
      const connected = nextAccounts.filter((account) => account.enabled && account.loginStatus === "logged_in" && account.connectionMode === "BrowserAutomation");
      const keys = [...new Set(connected.map((account) => account.platformKey))];
      const preferred = keys.includes("zhihu") ? "zhihu" : keys[0] ?? "";
      setAccounts(connected); setPlatforms(nextPlatforms); setQuality(nextQuality); setImages(nextImages); setPlatformKey(preferred);
    });
  }, [article.id, article.brandId]);
  useEffect(() => {
    setAccountId(defaultAccountSelection(availableAccounts).selectedAccountId ?? "");
  }, [availableAccounts]);
  const chooseRandom = useCallback(async (): Promise<void> => { const next = await window.publisherAPI.imageAssets.selectForArticle({ articleId: article.id, platformKey }); setSelectedImage(next); if (!next) setMessage("未找到可用配图，可以继续发布。"); }, [article.id, platformKey]);
  useEffect(() => { if (platformKey && imageMode === "random") void chooseRandom(); }, [chooseRandom, imageMode, platformKey]);
  const prepare = async (): Promise<void> => {
    if (!accountId || !platformKey) return;
    setBusy(true);
    try {
      const result = await window.publisherAPI.articles.preparePublish({ articleId: article.id, platformKey, platformAccountId: accountId, publishMode: "ASSISTED", selectedImageAssetId: imageMode === "none" ? null : selectedImage?.id ?? null, imageSelectionMode: imageMode });
      setMessage(`已打开${platformName}编辑器并填入文章，最终是否发布由你确认。记录 ${result.record?.status ?? "Prepared"}`); onDone();
    } catch (error) { setMessage(error instanceof Error ? error.message : "准备发布失败"); } finally { setBusy(false); }
  };
  const approved = quality?.status === "Approved";
  return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" onClick={(event) => event.stopPropagation()}><div className="drawer-head"><div><span className="eyebrow">发布到平台</span><h2>{article.title}</h2></div><button className="icon-button" onClick={onClose}>×</button></div><div className="hint-box">将把这篇文章发送到已连接的平台账号。若平台采用浏览器自动化，会自动打开对应编辑器并填入内容；最终是否正式发布，由你确认。</div>{!approved && <div className="notice error">这篇文章还没有通过内容审核，暂时不能发布到平台。请先前往 AI Quality Gate 完成审核。<button className="text-button" onClick={() => onNavigate("quality")}>去审核</button></div>}{platformKey && <label>发布到<select value={platformKey} onChange={(event) => setPlatformKey(event.target.value)}>{[...new Set(accounts.map((account) => account.platformKey))].map((key) => <option value={key} key={key}>{platforms.find((platform) => platform.platformKey === key)?.displayName ?? key}</option>)}</select></label>}{availableAccounts.length === 0 && <div className="notice">没有已连接的平台账号，请先在账号管理完成官方登录。</div>}{availableAccounts.length === 1 && <div className="account-auto-selected">{platformName}账号：{availableAccounts[0]?.name}（已自动选择）</div>}{availableAccounts.length > 1 && <label>{platformName}账号<select value={accountId} onChange={(event) => setAccountId(event.target.value)}><option value="">请选择账号</option>{availableAccounts.map((account) => <option value={account.platformAccountId ?? account.id} key={account.platformAccountId ?? account.id}>{account.name}</option>)}</select></label>}
    <section className="publish-image-section"><div className="panel-heading"><div><h3>配图</h3><span>默认自动随机选择；知乎当前先保存选择结果，不虚报已插入编辑器。</span></div></div><div className="image-choice-row"><label className="check-row"><input type="radio" name="image-mode" checked={imageMode === "random"} onChange={() => setImageMode("random")} /><span>自动随机选择</span></label><label className="check-row"><input type="radio" name="image-mode" checked={imageMode === "manual"} onChange={() => setImageMode("manual")} /><span>手动选择图片</span></label><label className="check-row"><input type="radio" name="image-mode" checked={imageMode === "none"} onChange={() => { setImageMode("none"); setSelectedImage(null); }} /><span>不使用图片</span></label></div>{imageMode === "random" && <button className="secondary-button" onClick={() => void chooseRandom()}>更换随机图片</button>}{imageMode !== "none" && selectedImage && <div className="selected-image-preview">{selectedImage.previewUrl && <img src={selectedImage.previewUrl} alt={selectedImage.name} />}<div><strong>{selectedImage.name}</strong><span>{selectedImage.universal ? "通用图片" : "已按业务/城市/平台匹配"}</span></div></div>}{imageMode === "manual" && <div className="manual-image-list">{images.map((image) => <button className={`manual-image-option ${selectedImage?.id === image.id ? "selected" : ""}`} key={image.id} onClick={() => setSelectedImage(image)}>{image.previewUrl && <img src={image.previewUrl} alt={image.name} />}<span>{image.name}</span></button>)}</div>}{imageMode !== "none" && !selectedImage && <div className="notice">未找到可用配图，仍可以继续发布。</div>}</section>
    {message && <div className="notice success">{message}</div>}<div className="hint-box">底层仍会保存发布记录，浏览器自动化只负责打开编辑器并填写标题、正文；不会点击最终发布，也不会绕过验证码或风控。</div><div className="drawer-footer"><button className="secondary-button" onClick={onClose}>取消</button><button className="primary-button" disabled={busy || !approved || !accountId || !platformKey} onClick={() => void prepare()}>{busy ? "准备中…" : `打开${platformName || "平台"}并填写文章`}</button></div></aside></div>;
}

function ArticlesPage({ refresh, onNavigate }: { refresh: () => void; onNavigate: (route: Route) => void }): JSX.Element {
  const [articles, setArticles] = useState<Article[]>([]); const [brands, setBrands] = useState<Brand[]>([]); const [brandId, setBrandId] = useState(""); const [search, setSearch] = useState(""); const [source, setSource] = useState<"production" | "content_studio" | "excel_import" | "benchmark" | "mock" | "test">("production"); const [selected, setSelected] = useState<Article | null>(null); const [publishArticle, setPublishArticle] = useState<Article | null>(null); const [excelPreview, setExcelPreview] = useState<NonNullable<Awaited<ReturnType<typeof window.publisherAPI.articles.importExcel>>> | null>(null); const [notice, setNotice] = useState("");
  const load = (): void => { void window.publisherAPI.articles.list({ brandId: brandId || undefined, search: search || undefined, source }).then(setArticles); };
  useEffect(() => { void window.publisherAPI.brands.list().then((list) => { setBrands(list); if (list[0]) setBrandId(list[0].id); }); }, []); useEffect(() => { void window.publisherAPI.articles.list({ brandId: brandId || undefined, search: search || undefined, source }).then(setArticles); }, [brandId, refresh, search, source]);
  const importExcel = async (): Promise<void> => { try { const preview = await window.publisherAPI.articles.importExcel(); if (preview) setExcelPreview(preview); } catch (error) { setNotice(error instanceof Error ? error.message : "Excel 预览失败"); } };
  const downloadSimpleTemplate = async (): Promise<void> => { const result = await window.publisherAPI.articles.downloadSimpleTemplate(); if (result) setNotice(`简易模板已保存：${result.fileName}`); };
  const downloadAdvancedTemplate = async (): Promise<void> => { const result = await window.publisherAPI.articles.downloadAdvancedTemplate(); if (result) setNotice(`高级模板已保存：${result.fileName}`); };
  return <><PageTitle eyebrow="内容管理" title="文章库" description="默认只展示正式生产内容；Excel 导入先预览、再确认，不会自动创建发布任务。" action={<div className="row-actions"><button className="secondary-button" onClick={() => void downloadSimpleTemplate()}>下载简易模板</button><button className="secondary-button" onClick={() => void downloadAdvancedTemplate()}>下载高级模板</button><button className="primary-button" onClick={() => void importExcel()}>Excel 导入</button><button className="primary-button" onClick={() => onNavigate("studio")}>＋ Content Studio</button></div>} />{notice && <div className="notice success">{notice}</div>}<div className="toolbar panel"><div className="search-box">⌕<input placeholder="搜索标题、关键词或正文" value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") load(); }} /></div><select value={brandId} onChange={(event) => setBrandId(event.target.value)}><option value="">全部品牌</option>{brands.map((brand) => <option value={brand.id} key={brand.id}>{brand.name}</option>)}</select><select value={source} onChange={(event) => setSource(event.target.value as typeof source)}><option value="production">Production（正式）</option><option value="excel_import">Excel 导入</option><option value="content_studio">Content Studio</option><option value="benchmark">Benchmark</option><option value="mock">Mock</option><option value="test">Test</option></select><button className="secondary-button" onClick={load}>筛选</button></div><section className="panel table-panel"><div className="table-summary"><span>{source} · 共 {articles.length} 篇内容</span><div className="table-tabs"><button className="active">正式来源隔离</button><span className="hint-box">Benchmark 不进入正式可用文章统计</span></div></div>{articles.length === 0 ? <EmptyState title="暂无文章" description="可以下载简易模板导入，或前往 AI Content Studio 生成正式内容。" action={<button className="secondary-button" onClick={() => onNavigate("studio")}>去生成文章</button>} /> : <div className="data-table"><div className="table-head article-head"><span>标题 / 关键词</span><span>城市</span><span>来源 / 类型</span><span>字数</span><span>状态</span><span>操作</span></div>{articles.map((article) => <div className="table-row article-row" key={article.id}><div className="article-title"><div className="cover-thumb">{article.coverAssetId ? "▧" : "—"}</div><div><strong>{article.title}</strong><span>{article.keyword}</span></div></div><span>{article.city}</span><span>{article.source ?? "production"} · {article.articleType}</span><span>{article.body.length.toLocaleString()}</span><div><StatusPill status={article.needsRewrite ? "NeedsRewrite" : article.status} />{article.needsRewrite && <small>需品牌版重写</small>}</div><div className="row-actions"><button className="mini-button" onClick={() => setSelected(article)}>查看</button>{["production", "content_studio", "excel_import"].includes(article.source ?? "production") && <button className="mini-button" onClick={() => setPublishArticle(article)}>发布</button>}{article.needsRewrite && <><button className="mini-button" onClick={() => void window.publisherAPI.articles.markNeedsRewrite(article.id).then(() => onNavigate("studio"))}>重新生成品牌版</button><button className="mini-button" onClick={() => void window.publisherAPI.articles.archive(article.id).then(() => { load(); refresh(); })}>归档</button></>}{!article.needsRewrite && article.status !== "archived" && <button className="mini-button" onClick={() => void window.publisherAPI.articles.generateCover(article.id).then(() => { load(); refresh(); })}>封面</button>}</div></div>)}</div>}</section>{selected && <ArticleDrawer article={selected} onClose={() => setSelected(null)} onSaved={() => { setSelected(null); load(); }} />}{publishArticle && <SimpleArticlePublishModal article={publishArticle} onClose={() => setPublishArticle(null)} onDone={() => { load(); refresh(); }} onNavigate={onNavigate} />}{excelPreview && <ExcelImportModal preview={excelPreview} brands={brands} onClose={() => setExcelPreview(null)} onComplete={() => { load(); refresh(); }} />}</>;
}

function ArticleDrawer({ article, onClose, onSaved }: { article: Article; onClose: () => void; onSaved: () => void }): JSX.Element { const [title, setTitle] = useState(article.title); const [body, setBody] = useState(article.body); const [history, setHistory] = useState<Awaited<ReturnType<typeof window.publisherAPI.articles.history>>>([]); useEffect(() => { void window.publisherAPI.articles.history(article.id).then(setHistory); }, [article.id]); return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" onClick={(event) => event.stopPropagation()}><div className="drawer-head"><div><span className="eyebrow">文章详情</span><h2>编辑内容</h2></div><button className="icon-button" onClick={onClose}>×</button></div><label>标题<input value={title} onChange={(event) => setTitle(event.target.value)} /></label><label>正文<textarea rows={12} value={body} onChange={(event) => setBody(event.target.value)} /></label><div className="hint-box">生成来源：{article.source ?? "production"} · Provider {article.aiProvider} · Model {article.aiModel}<br />Brand：{article.brandId} · Goal：{article.contentGoal ?? "未记录"} · Content Intent：{article.contentIntent ?? "未记录"} · Search Intent：{article.searchIntent ?? "未记录"}<br />City：{article.city} · Platform：{article.contentStudioTaskId ? "Content Studio" : "通用文章"} · Knowledge facts：{article.knowledgeSnapshot?.factCount ?? 0} · Brand differentiation：{article.brandDifferentiationScore ?? "未记录"} · Prompt version：{article.promptVersion ?? "未记录"}{article.benchmarkRunId ? <><br />Benchmark：{article.benchmarkId} · Run：{article.benchmarkRunId}</> : ""}{article.needsRewrite ? <><br />Content state：NeedsRewrite / Archived</> : ""}</div><div className="panel-heading"><div><h3>使用的企业事实摘要</h3><span>只显示已持久化的非敏感知识快照</span></div></div>{article.knowledgeSnapshot?.facts?.length ? <div className="studio-selection">{article.knowledgeSnapshot.facts.map((fact) => <small key={fact.id}>[{fact.type}] {fact.label}：{fact.content}</small>)}</div> : <div className="hint-box">该内容没有 Content Studio 知识快照。</div>}<div className="hint-box">Quality Gate：{article.qualityStatus ?? "unchecked"}{article.qualityWarnings?.length ? ` · ${article.qualityWarnings.join("；")}` : ""}</div><div className="panel-heading"><div><h3>发布历史</h3><span>包括 dry-run、Publishing 和最终结果</span></div></div>{history.length === 0 ? <EmptyState compact title="尚未发布" description="这篇文章还没有 PublishRecord。" /> : <div className="log-list">{history.map((record) => <div className="log-row" key={record.id}><strong>{record.platformKey}</strong><span>{record.status ?? (record.success ? "Published" : "Failed")}</span><span>{new Date(record.publishedAt).toLocaleString("zh-CN")}</span>{record.publishedUrl && <span>{record.publishedUrl}</span>}</div>)}</div>}<div className="drawer-footer"><button className="secondary-button" onClick={onClose}>取消</button><button className="primary-button" onClick={() => void window.publisherAPI.articles.update(article.id, { title, body }).then(onSaved)}>保存修改</button></div></aside></div>; }

function BrandPage({ knowledgeOnly, refresh }: { knowledgeOnly: boolean; refresh: () => void }): JSX.Element { const [brand, setBrand] = useState<Brand | null>(null); const [form, setForm] = useState<Record<string, string>>({}); const [saved, setSaved] = useState(false); useEffect(() => { void window.publisherAPI.brands.list().then((list) => { const first = list[0]; if (first) { setBrand(first); setForm({ name: first.name, companyName: first.companyName, description: first.description, mainBusiness: first.mainBusiness, address: first.address, serviceProcess: first.serviceProcess, afterSales: first.afterSales, faq: first.faq, certificates: first.certificates, patents: first.patents, equipment: first.equipment, cases: first.cases, aiForbiddenClaims: first.aiForbiddenClaims.join("\n") }); } }); }, []); const save = async (): Promise<void> => { if (!brand) return; await window.publisherAPI.brands.update(brand.id, { ...form, aiForbiddenClaims: (form.aiForbiddenClaims ?? "").split(/\r?\n/).filter(Boolean) }); setSaved(true); refresh(); window.setTimeout(() => setSaved(false), 2200); }; const field = (key: string, label: string, multiline = false): JSX.Element => <label>{label}{multiline ? <textarea rows={4} value={form[key] ?? ""} onChange={(event) => setForm({ ...form, [key]: event.target.value })} /> : <input value={form[key] ?? ""} onChange={(event) => setForm({ ...form, [key]: event.target.value })} />}</label>; return <><PageTitle eyebrow={`品牌中心 / ${knowledgeOnly ? "企业知识库" : "企业资料"}`} title={knowledgeOnly ? "企业知识库" : "企业资料"} description="这些资料会进入 Prompt Builder，并作为 AI 禁止编造边界。" action={<button className="primary-button" onClick={() => void save()}>保存资料</button>} />{saved && <div className="notice success floating-notice">✓ 品牌资料已保存到 SQLite</div>}<div className="form-layout"><section className="panel form-panel"><div className="panel-heading"><div><h3>基础信息</h3><span>品牌与企业身份</span></div></div>{field("name", "品牌名称")}{field("companyName", "公司名称")}{field("description", "公司介绍", true)}{field("mainBusiness", "主营业务", true)}{field("address", "公司地址")}{field("serviceProcess", "服务流程", true)}{field("afterSales", "售后服务", true)}</section><section className="panel form-panel"><div className="panel-heading"><div><h3>可信资料边界</h3><span>只填写可以被真实材料支持的内容</span></div></div>{field("faq", "FAQ", true)}{field("certificates", "证书资质说明", true)}{field("patents", "专利说明", true)}{field("equipment", "设备说明", true)}{field("cases", "案例说明", true)}<label className="danger-label">AI 禁止编造项<textarea rows={6} value={form.aiForbiddenClaims ?? ""} onChange={(event) => setForm({ ...form, aiForbiddenClaims: event.target.value })} placeholder="每行一条，例如：禁止虚构客户名称" /></label><div className="hint-box">这些约束会自动注入每次 Mock AI 生成任务的 Prompt。</div></section></div></>; }

function AccountsPage({ refresh }: { refresh: () => void }): JSX.Element { const [accounts, setAccounts] = useState<Account[]>([]); const [platforms, setPlatforms] = useState<Platform[]>([]); const [name, setName] = useState(""); const [platformKey, setPlatformKey] = useState("test"); const load = (): void => { void window.publisherAPI.accounts.list().then(setAccounts); }; useEffect(() => { void Promise.all([window.publisherAPI.platforms.list(), window.publisherAPI.accounts.list()]).then(([nextPlatforms, nextAccounts]) => { setPlatforms(nextPlatforms); setAccounts(nextAccounts); }); }, [refresh]); const create = async (): Promise<void> => { if (!name.trim()) return; await window.publisherAPI.accounts.create({ platformKey, name }); setName(""); load(); refresh(); }; return <><PageTitle eyebrow="账号管理" title="全部账号" description="账号模型不设产品级数量上限；真实登录与发布仍需要用户授权。" /><div className="inline-create panel"><select value={platformKey} onChange={(event) => setPlatformKey(event.target.value)}>{platforms.map((platform) => <option value={platform.platformKey} key={platform.platformKey}>{platform.displayName}</option>)}</select><input placeholder="新增账号名称，例如：测试账号04" value={name} onChange={(event) => setName(event.target.value)} /><button className="primary-button" onClick={() => void create()}>添加账号</button></div><section className="account-grid">{accounts.map((account) => <div className="panel account-card" key={account.id}><div className="account-top"><div className="platform-avatar">{account.platformKey.slice(0, 1).toUpperCase()}</div><div><strong>{account.name}</strong><span>{account.platformKey}</span></div><button className={`toggle ${account.enabled ? "on" : ""}`} onClick={() => void window.publisherAPI.accounts.update(account.id, { enabled: !account.enabled }).then(load)}><span /></button></div><div className="account-meta"><div><span>登录状态</span><StatusPill status={account.loginStatus} /></div><div><span>今日发布</span><b>{account.todayPublishCount}</b></div><div><span>最近发布</span><b>{account.lastPublishAt ? new Date(account.lastPublishAt).toLocaleDateString("zh-CN") : "暂无"}</b></div></div>{account.pausedReason && <div className="account-warning">⚠ {account.pausedReason}</div>}<button className="secondary-button wide" onClick={() => void window.publisherAPI.accounts.update(account.id, { loginStatus: "logged_in", pausedReason: null }).then(load)}>模拟检查登录</button></div>)}</section></>; }

function PlatformsPage(): JSX.Element { const [platforms, setPlatforms] = useState<Platform[]>([]); useEffect(() => { void window.publisherAPI.platforms.list().then(setPlatforms); }, []); return <><PageTitle eyebrow="账号管理 / 平台管理" title="平台能力目录" description="平台 selector 和登录流程隔离在 Adapter；当前仅 TestPlatform 可运行。" /><section className="platform-grid">{platforms.map((platform, index) => <div className="platform-card" key={platform.platformKey}><div className={`platform-logo logo-${index % 6}`}>{platform.platformKey === "test" ? "T" : platform.displayName.slice(0, 1)}</div><strong>{platform.displayName}</strong><span>{platform.category}</span><StatusPill status={platform.adapterStatus} /></div>)}</section></>; }

function PlansPage({ refresh }: { refresh: () => void }): JSX.Element { const [brands, setBrands] = useState<Brand[]>([]); const [accounts, setAccounts] = useState<Account[]>([]); const [plans, setPlans] = useState<PublishPlan[]>([]); const [brandId, setBrandId] = useState(""); const [selectedAccounts, setSelectedAccounts] = useState<string[]>([]); const [name, setName] = useState("工作日内容排期"); const [createdPlan, setCreatedPlan] = useState<string | null>(null); useEffect(() => { void Promise.all([window.publisherAPI.brands.list(), window.publisherAPI.accounts.list(), window.publisherAPI.plans.list()]).then(([nextBrands, nextAccounts, nextPlans]) => { setBrands(nextBrands); setAccounts(nextAccounts); setPlans(nextPlans); if (nextBrands[0]) setBrandId(nextBrands[0].id); }); }, [refresh]); const create = async (): Promise<void> => { if (!brandId || selectedAccounts.length === 0) return; const plan = await window.publisherAPI.plans.create({ name, brandId, enabled: true, strategy: "same_article", articlesPerDay: 1, accountIds: selectedAccounts, publishTimes: ["09:30"], reusePolicy: "once", minIntervalSeconds: 60, maxRetries: 3, consecutiveFailureThreshold: 3, startDate: new Date().toISOString().slice(0, 10), endDate: null }); setCreatedPlan(plan.id); }; const generate = async (planId: string): Promise<void> => { await window.publisherAPI.plans.generateJobs(planId, new Date(Date.now() - 1000).toISOString()); refresh(); }; return <><PageTitle eyebrow="发布中心" title="发布计划" description="配置账号、内容策略和可预测的排期任务。" /><div className="form-layout"><section className="panel form-panel"><div className="panel-heading"><div><h3>新建计划</h3><span>任务生成后会持久化到 SQLite</span></div></div><label>计划名称<input value={name} onChange={(event) => setName(event.target.value)} /></label><label>品牌<select value={brandId} onChange={(event) => setBrandId(event.target.value)}>{brands.map((brand) => <option value={brand.id} key={brand.id}>{brand.name}</option>)}</select></label><label>内容分配策略<select defaultValue="same_article"><option value="same_article">全平台使用同一篇文章</option><option value="platform_variant">每个平台不同文章</option><option value="topic_rewrite">同主题按平台改写</option><option value="account_variant">每个账号不同文章</option></select></label><label>选择账号<div className="template-list">{accounts.map((account) => <label className="check-row" key={account.id}><input type="checkbox" checked={selectedAccounts.includes(account.id)} onChange={() => setSelectedAccounts((current) => current.includes(account.id) ? current.filter((id) => id !== account.id) : [...current, account.id])} /><span>{account.name}</span><em>{account.platformKey}</em></label>)}</div></label><button className="primary-button wide" disabled={!selectedAccounts.length} onClick={() => void create()}>保存发布计划</button>{createdPlan && <div className="notice success">计划已保存，可以生成今天的任务。</div>}</section><section className="panel table-panel"><div className="panel-heading"><div><h3>已保存计划</h3><span>执行前可以随时调整 scheduledAt 做本地验收</span></div></div>{plans.length === 0 ? <EmptyState compact title="还没有发布计划" description="左侧配置一个计划开始测试。" /> : <div className="plan-list">{plans.map((plan) => <div className="plan-row" key={plan.id}><div><strong>{plan.name}</strong><span>{plan.accountIds.length} 个账号 · 每天 {plan.articlesPerDay} 篇</span></div><button className="secondary-button" onClick={() => void generate(plan.id)}>生成今天任务</button></div>)}</div>}</section></div></>; }

function QueuePage({ refresh }: { refresh: () => void }): JSX.Element { const [jobs, setJobs] = useState<PublishJob[]>([]); const [running, setRunning] = useState<string | null>(null); const load = (): void => { void window.publisherAPI.jobs.list().then(setJobs); }; useEffect(load, [refresh]); const run = async (id: string): Promise<void> => { setRunning(id); await window.publisherAPI.jobs.run(id); setRunning(null); load(); refresh(); }; return <><PageTitle eyebrow="发布中心" title="发布队列" description="所有发布动作必须先进入持久化队列，支持重试与人工处理。" action={<button className="secondary-button" onClick={() => void window.publisherAPI.jobs.recover().then(load)}>恢复未完成任务</button>} /><section className="panel table-panel"><div className="table-summary"><span>共 {jobs.length} 个任务</span><div className="legend"><StatusPill status="Success" /><StatusPill status="Retry" /><StatusPill status="NeedsUserAction" /></div></div>{jobs.length === 0 ? <EmptyState title="队列为空" description="创建发布计划并生成今天任务。" /> : <div className="data-table"><div className="table-head queue-head"><span>任务</span><span>平台 / 账号</span><span>计划时间</span><span>尝试次数</span><span>状态</span><span>操作</span></div>{jobs.map((job) => <div className="table-row queue-row" key={job.id}><div><strong>{job.id.slice(0, 12)}</strong><span>文章 {job.articleId.slice(0, 8)}</span></div><span>{job.platformKey}<br /><small>{job.accountId.slice(0, 8)}</small></span><span>{new Date(job.scheduledAt).toLocaleString("zh-CN")}</span><span>{job.attemptCount} / {job.maxAttempts}</span><StatusPill status={job.status} /><div className="row-actions">{["Pending", "Scheduled", "Retry", "NeedsUserAction"].includes(job.status) && <button className="mini-button" disabled={running === job.id} onClick={() => void run(job.id)}>{running === job.id ? "执行中" : "立即执行"}</button>}{job.status === "Failed" && <button className="mini-button" onClick={() => void window.publisherAPI.jobs.retry(job.id).then(load)}>重试</button>}</div></div>)}</div>}</section></>; }

function AiTasksPage(): JSX.Element { const [stats, setStats] = useState<DashboardStats | null>(null); const [tasks, setTasks] = useState<ContentStudioTaskView[]>([]); useEffect(() => { void Promise.all([window.publisherAPI.dashboard.get(), window.publisherAPI.contentStudio.tasks()]).then(([nextStats, nextTasks]) => { setStats(nextStats); setTasks(nextTasks); }); }, []); return <><PageTitle eyebrow="AI 创作" title="AI 任务" description="任务进度与生成结果最终以数据库记录为准。" /><div className="stat-grid"><StatCard label="正在运行" value={stats?.activeAiTasks ?? 0} hint="后台任务" tone="purple" icon="◷" /><StatCard label="今日生成" value={stats?.generatedToday ?? 0} hint="已写入文章库" tone="green" icon="✦" /><StatCard label="内容库存" value={stats?.availableArticles ?? 0} hint="可用于排期" icon="▤" /></div><section className="panel table-panel"><div className="panel-heading"><div><h3>AI Content Studio 任务记录</h3><span>Provider、Model、输入范围、进度、耗时和错误信息均来自本地持久化记录。</span></div></div>{tasks.length === 0 ? <EmptyState title="暂无 AI 任务" description="从 AI Content Studio 生成主题规划或多平台内容后，任务会显示在这里。" /> : <div className="log-list">{tasks.slice(0, 30).map((task) => <div className="log-row" key={task.id}><strong>{task.type}</strong><span>{task.provider} / {task.model}</span><span>{task.completed} / {task.total} · {task.durationMs} ms</span><div><StatusPill status={task.status} />{task.errorMessage && <small>{task.errorMessage}</small>}</div></div>)}</div>}</section></>; }

function AssetsPage(): JSX.Element { return <><PageTitle eyebrow="内容管理" title="企业素材库" description="本地保存文件路径与元数据，暂不接入云存储。" /><section className="asset-type-grid">{["企业 Logo", "公司环境", "团队", "施工照片", "产品", "设备", "证书", "案例", "其他"].map((item, index) => <div className="panel asset-type" key={item}><div className={`asset-icon asset-${index % 5}`}>▧</div><strong>{item}</strong><span>本地素材管理</span><button className="text-button">查看素材 →</button></div>)}</section></>; }

function StatisticsPage(): JSX.Element { const [stats, setStats] = useState<DashboardStats | null>(null); const [logs, setLogs] = useState<{ id: string; level: string; module: string; code: string; message: string; timestamp: string }[]>([]); useEffect(() => { void Promise.all([window.publisherAPI.dashboard.get(), window.publisherAPI.logs.list(8)]).then(([nextStats, nextLogs]) => { setStats(nextStats); setLogs(nextLogs); }); }, []); return <><PageTitle eyebrow="数据中心" title="发布统计" description="指标来自本地数据库中的任务与发布记录。" /><div className="stat-grid"><StatCard label="今日发布" value={stats?.publishedToday ?? 0} hint="成功写入 PublishRecord" icon="↗" /><StatCard label="失败任务" value={stats?.failedJobs ?? 0} hint="需要人工关注" tone="orange" icon="!" /><StatCard label="待发布" value={stats?.pendingJobs ?? 0} hint="队列中" tone="purple" icon="◷" /><StatCard label="生成内容" value={stats?.generatedToday ?? 0} hint="今日 AI 产出" tone="green" icon="✦" /></div><section className="panel table-panel"><div className="panel-heading"><div><h3>最近系统日志</h3><span>结构化日志 · 便于审计</span></div></div>{logs.length === 0 ? <EmptyState compact title="暂无异常日志" description="系统运行事件会记录在这里。" /> : <div className="log-list">{logs.map((log) => <div className="log-row" key={log.id}><span>{new Date(log.timestamp).toLocaleString("zh-CN")}</span><b className={log.level}>{log.level}</b><strong>{log.module}</strong><span>{log.message}</span></div>)}</div>}</section></>; }

function SettingsPage(): JSX.Element { const [settings, setSettings] = useState<Record<string, unknown>>({}); useEffect(() => { void window.publisherAPI.settings.get().then(setSettings); }, []); const save = (key: string, value: string | number): void => { setSettings({ ...settings, [key]: value }); void window.publisherAPI.settings.update(key, value); }; return <><PageTitle eyebrow="系统设置 / AI 设置" title="AI 设置" description="Provider 抽象已就位；V0.1 默认使用 Mock AI，不读取 Renderer 中的敏感凭据。" action={<span className="status-chip success">● Mock Provider 可用</span>} /><div className="settings-layout"><section className="panel form-panel"><div className="panel-heading"><div><h3>Provider 配置</h3><span>真实 API Key 将在后续版本接入安全存储</span></div></div><label>Provider<select value={String(settings.provider ?? "mock")} onChange={(event) => save("provider", event.target.value)}><option value="mock">Mock AI Provider</option><option value="openai">OpenAI（未接入）</option><option value="custom">自定义 Provider（未接入）</option></select></label><label>Model<input value={String(settings.model ?? "mock-editor-v0.1")} onChange={(event) => save("model", event.target.value)} /></label><label>API Key<div className="secret-field"><input value={settings.apiKeyConfigured ? "已配置（安全存储）" : "未配置"} readOnly /><span>🔒</span></div></label><div className="hint-box">Renderer 只能看到脱敏状态，不能读取 API Key、Cookie 或 StorageState 文件。</div></section><section className="panel form-panel"><div className="panel-heading"><div><h3>执行参数</h3><span>影响 AI 任务与队列吞吐</span></div></div><label>请求超时（毫秒）<input type="number" value={Number(settings.timeout ?? 30000)} onChange={(event) => save("timeout", Number(event.target.value))} /></label><label>并发数量<input type="number" value={Number(settings.concurrency ?? 2)} onChange={(event) => save("concurrency", Number(event.target.value))} /></label><label>失败重试次数<input type="number" value={Number(settings.retry ?? 2)} onChange={(event) => save("retry", Number(event.target.value))} /></label><div className="notice">ℹ 当前任务使用 Mock Provider，不需要 API Key 即可完整演示。</div></section></div></>; }

function LogsPage(): JSX.Element {
  const [logs, setLogs] = useState<ActivityLog[]>([]);
  const [search, setSearch] = useState("");
  const [message, setMessage] = useState("");
  const load = (): void => { void window.publisherAPI.logs.list(300, { search: search || undefined }).then(setLogs); };
  useEffect(() => { void window.publisherAPI.logs.list(300, { search: search || undefined }).then(setLogs); }, [search]);
  return <><PageTitle eyebrow="数据中心 / 运行日志" title="运行日志" description="默认展示脱敏后的结构化日志；API Key、Cookie、Secret 和 Authorization 不会导出。" action={<><button className="secondary-button" onClick={() => void window.publisherAPI.logs.export().then((path) => setMessage(path ? "日志包已导出" : "已取消导出"))}>导出诊断 ZIP</button></>} />{message && <div className="notice success">✓ {message}</div>}<div className="toolbar panel"><div className="search-box">⌕<input placeholder="搜索模块、错误码或消息" value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") load(); }} /></div><button className="secondary-button" onClick={load}>搜索</button></div><section className="panel table-panel"><div className="table-summary"><span>最近 {logs.length} 条</span></div>{logs.length === 0 ? <EmptyState compact title="暂无日志" description="系统运行事件会记录在这里。" /> : <div className="log-list">{logs.map((log) => <div className="log-row" key={log.id}><span>{new Date(log.timestamp).toLocaleString("zh-CN")}</span><b className={log.level}>{log.level}</b><strong>{log.module}</strong><span>{log.code}</span><span>{log.message}</span></div>)}</div>}</section></>;
}

function BackupsPage(): JSX.Element {
  const [backups, setBackups] = useState<string[]>([]);
  const [message, setMessage] = useState("");
  const load = (): void => { void window.publisherAPI.backups.list().then(setBackups); };
  useEffect(load, []);
  const create = async (): Promise<void> => { const path = await window.publisherAPI.backups.create(); setMessage(`已创建备份：${path}`); load(); };
  const restore = async (path: string): Promise<void> => { if (!window.confirm("恢复备份会关闭并重启应用，当前数据库将被替换。确定继续吗？")) return; await window.publisherAPI.backups.restore(path); };
  return <><PageTitle eyebrow="系统设置 / 数据备份" title="数据备份" description="使用 SQLite 在线备份 API 创建一致性快照；恢复前会执行完整性校验并要求二次确认。" action={<button className="primary-button" onClick={() => void create()}>立即备份</button>} />{message && <div className="notice success">✓ {message}</div>}<section className="panel table-panel"><div className="panel-heading"><div><h3>备份历史</h3><span>备份保存在 Electron userData/backups，不写入源码目录。</span></div></div>{backups.length === 0 ? <EmptyState compact title="暂无备份" description="建议在真实平台联调前先创建备份。" /> : <div className="log-list">{backups.map((path) => <div className="log-row" key={path}><strong>{path.split(/[\\/]/u).pop()}</strong><span>{path}</span><button className="mini-button" onClick={() => void window.publisherAPI.backups.validate(path).then((result) => setMessage(result.message))}>校验</button><button className="mini-button danger-mini" onClick={() => void restore(path)}>恢复</button></div>)}</div>}</section></>;
}

function AccountsCenterPage({ refresh }: { refresh: () => void }): JSX.Element {
  const [overview, setOverview] = useState<AccountManagementRow[]>([]);
  const [platforms, setPlatforms] = useState<Platform[]>([]);
  const [name, setName] = useState("");
  const [platformKey, setPlatformKey] = useState("test");
  const [credentials, setCredentials] = useState<Record<string, Record<string, string>>>({});
  const [credentialStatus, setCredentialStatus] = useState<Record<string, Awaited<ReturnType<typeof window.publisherAPI.accounts.credentialStatus>>>>({});
  const [loginSessions, setLoginSessions] = useState<Record<string, Awaited<ReturnType<typeof window.publisherAPI.accounts.beginLogin>>>>({});
  const [callbackUrls, setCallbackUrls] = useState<Record<string, string>>({});
  const [messages, setMessages] = useState<Record<string, string>>({});
  const [wizardAccountId, setWizardAccountId] = useState<string | null>(null);
  const [douyinWizardAccountId, setDouyinWizardAccountId] = useState<string | null>(null);
  const load = (): void => { void Promise.all([window.publisherAPI.accounts.overview(), window.publisherAPI.platforms.list()]).then(([nextOverview, nextPlatforms]) => { setOverview(nextOverview); setPlatforms(nextPlatforms); }); };
  useEffect(load, [refresh]);
  const create = async (): Promise<void> => { if (!name.trim()) return; await window.publisherAPI.accounts.create({ platformKey, name }); setName(""); load(); refresh(); };
  const saveCredentials = async (account: Account): Promise<void> => {
    const values = Object.fromEntries(Object.entries(credentials[account.id] ?? {}).filter(([, value]) => value.trim()));
    if (Object.keys(values).length === 0) return;
    try {
      const status = await window.publisherAPI.accounts.setCredentials({ accountId: account.id, platformKey: account.platformKey, values });
      setCredentials((current) => ({ ...current, [account.id]: {} }));
      setCredentialStatus((current) => ({ ...current, [account.id]: { ...status, expired: false } }));
      setMessages((current) => ({ ...current, [account.id]: status.configured ? "所需凭据已通过 safeStorage 加密保存" : "凭据已加密保存，仍有必填项未配置" }));
      load();
    } catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "凭据保存失败" })); }
  };
  const beginLogin = async (account: Account): Promise<void> => {
    try {
      const session = await window.publisherAPI.accounts.beginLogin(account.id, account.platformKey);
      setLoginSessions((current) => ({ ...current, [account.id]: session }));
      setMessages((current) => ({ ...current, [account.id]: session.message ?? "请完成平台正常授权" }));
      load();
    } catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "授权启动失败" })); }
  };
  const completeLogin = async (account: Account): Promise<void> => {
    const callbackUrl = callbackUrls[account.id]?.trim();
    if (!callbackUrl) return;
    try {
      await window.publisherAPI.accounts.completeLogin(account.id, account.platformKey, callbackUrl);
      beginPostLoginHeartbeat(account.id, account.platformKey);
      setCallbackUrls((current) => ({ ...current, [account.id]: "" }));
      setMessages((current) => ({ ...current, [account.id]: "OAuth 授权已安全完成" }));
      load();
    } catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "OAuth 回调处理失败" })); }
  };
  const testConnection = async (account: Account): Promise<void> => {
    try {
      await runCheckLoginWithHeartbeats(account.id, account.platformKey, () => window.publisherAPI.accounts.checkLogin(account.id, account.platformKey));
      setMessages((current) => ({ ...current, [account.id]: "连接测试完成；未改变平台生命周期" }));
      load();
    } catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "连接测试失败；未改变平台生命周期" })); }
  };
  const disconnect = async (account: Account): Promise<void> => {
    if (!window.confirm("移除后会清除此账号的登录状态和本地会话，但不会删除历史发布记录。确定继续吗？")) return;
    try { const result = await window.publisherAPI.accounts.disconnect(account.id, account.platformKey); setMessages((current) => ({ ...current, [account.id]: disconnectFeedbackMessage(result, account.accountAlias || account.name) })); load(); }
    catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "移除失败" })); }
  };
  const wizardRow = overview.find((row) => row.account.id === wizardAccountId && row.account.platformKey === "wechat_official");
  if (wizardRow) return <WeChatVerificationWizard account={wizardRow.account} platform={wizardRow.platform} credentialStatus={credentialStatus[wizardRow.account.id] ?? wizardRow.credentialStatus} onBack={() => setWizardAccountId(null)} refresh={refresh} />;
  const douyinWizardRow = overview.find((row) => row.account.id === douyinWizardAccountId && row.account.platformKey === "douyin");
  if (douyinWizardRow) return <DouyinVerificationWizard account={douyinWizardRow.account} platform={douyinWizardRow.platform} credentialStatus={credentialStatus[douyinWizardRow.account.id] ?? douyinWizardRow.credentialStatus} onBack={() => setDouyinWizardAccountId(null)} refresh={refresh} />;
  return <><PageTitle eyebrow="平台账号配置中心 / V0.6.1" title="平台账号管理" description="统一查看 Adapter、账号、Credential、授权和验证时间。所有 Secret 通过 safeStorage 保存；测试连接只更新账号连接结果，不改变平台生命周期。" /><div className="inline-create panel"><select value={platformKey} onChange={(event) => setPlatformKey(event.target.value)}>{platforms.map((platform) => <option value={platform.platformKey} key={platform.platformKey}>{platform.displayName}</option>)}</select><input placeholder="新增账号名称" value={name} onChange={(event) => setName(event.target.value)} /><button className="primary-button" onClick={() => void create()}>添加账号</button></div><section className="account-grid">{overview.length === 0 ? <EmptyState title="暂无平台账号" description="先选择平台并添加账号，再配置平台凭据。" /> : overview.map((row) => {
    const account = row.account;
    const platform = row.platform;
    const values = credentials[account.id] ?? {};
    const status = credentialStatus[account.id] ?? row.credentialStatus;
    const session = loginSessions[account.id];
    const fields = platform?.credentialSchema ?? [];
    const isBrowserPlatform = platform?.transport === "browser";
    const canConnect = Boolean(platform && (isBrowserPlatform || ["OAuth2", "OAuth2PKCE"].includes(platform.authStrategy)) && !["Blocked", "NotImplemented", "ManualOnly"].includes(platform.verificationStatus));
    return <div className="panel account-card" key={account.id}><div className="account-top"><div className="platform-avatar">{(platform?.displayName ?? account.platformKey).slice(0, 1).toUpperCase()}</div><div><strong>{platform?.displayName ?? account.platformKey}</strong><span>{row.providerAccountName ?? account.name}</span></div><button className={`toggle ${account.enabled ? "on" : ""}`} aria-label={account.enabled ? "停用账号" : "启用账号"} onClick={() => void window.publisherAPI.accounts.update(account.id, { enabled: !account.enabled }).then(load)}><span /></button></div><div className="account-meta account-center-meta"><div><span>平台名称</span><b>{platform?.displayName ?? "未知平台"}</b></div><div><span>接入方式</span><b>{integrationModeLabel(platform)}</b></div><div><span>Adapter 状态</span><StatusPill status={platform?.adapterStatus ?? "unknown"} /></div><div><span>账号状态</span><StatusPill status={row.accountStatus} /></div><div><span>Credential 状态</span><StatusPill status={status.configured ? "已配置" : "未配置"} /></div><div><span>授权状态</span><StatusPill status={row.authorizationStatus} /></div><div><span>Publish 状态</span><StatusPill status={row.publishVerification} /></div><div><span>授权范围</span><b>{row.authorizationScopes.length > 0 ? `${row.authorizationScopes.length} 项` : "未读取"}</b></div><div><span>授权过期时间</span><b>{formatAccountDate(row.authorizationExpiresAt)}</b></div><div><span>最后 Dry Run 时间</span><b>{formatAccountDate(row.lastDryRunAt)}</b></div><div><span>最后发布时间</span><b>{formatAccountDate(account.lastPublishAt)}</b></div></div>{fields.length > 0 && <div className="credential-box"><div className="credential-heading">平台凭据（保存后不回显 Secret）</div>{fields.map((field) => <label key={field.key}>{field.label}{status.fields.find((item) => item.key === field.key)?.configured && <small>已配置</small>}<input type={field.type === "secret" ? "password" : "text"} value={values[field.key] ?? ""} placeholder={field.required ? "必填；保存后不回显" : "可选；保存后不回显"} onChange={(event) => setCredentials((current) => ({ ...current, [account.id]: { ...values, [field.key]: event.target.value } }))} /></label>)}<button className="secondary-button wide" onClick={() => void saveCredentials(account)}>保存到安全存储</button><button className="text-button" onClick={() => void window.publisherAPI.accounts.credentialStatus(account.id, account.platformKey).then((next) => setCredentialStatus((current) => ({ ...current, [account.id]: next })))}>刷新 Credential 状态</button>{canConnect && row.accountStatus !== "Connected" && <div className="row-actions"><button className="mini-button" onClick={() => void beginLogin(account)}>连接账号</button></div>}{isBrowserPlatform && session && <><small>真实浏览器窗口已打开。请完成登录后保存加密 Session。</small><button className="secondary-button wide" onClick={() => void completeLogin(account)}>已完成登录并保存 Session</button></>}{session?.authorizationUrl && <><small>官方授权页已在系统浏览器中打开。</small><label>粘贴完整 callback URL 或 authorization code<input value={callbackUrls[account.id] ?? ""} onChange={(event) => setCallbackUrls((current) => ({ ...current, [account.id]: event.target.value }))} /></label><button className="secondary-button wide" onClick={() => void completeLogin(account)}>完成 OAuth</button></>}</div>}{canConnect && <div className="row-actions connection-test-row">{row.accountStatus === "Connected" ? <button className="mini-button" onClick={() => void testConnection(account)}>测试连接</button> : <button className="mini-button" onClick={() => void beginLogin(account)}>连接账号</button>}{row.accountStatus === "Connected" || row.accountStatus === "Expired" || row.accountStatus === "NeedsLogin" || row.authorizationStatus === "Revoked" ? <button className="mini-button" onClick={() => void beginLogin(account)}>{isBrowserPlatform ? "重新登录" : "重新授权"}</button> : null}{isBrowserPlatform && row.accountStatus === "Connected" && <button className="mini-button" onClick={() => void window.publisherAPI.accounts.openBackend(account.id, account.platformKey)}>打开后台</button>}{row.accountStatus !== "NotConnected" && <button className="mini-button danger-mini" onClick={() => void disconnect(account)}>移除</button>}<small>{isBrowserPlatform ? "Playwright 使用加密 Session；验证码和安全验证由用户完成" : "OAuth 在系统浏览器中完成"}</small></div>}{!canConnect && <div className="row-actions connection-test-row"><small>{platform?.blockingReason ?? "当前平台暂无已验证的官方自动登录接入"}</small></div>}{account.platformKey === "wechat_official" && <button className="text-button wechat-wizard-link" onClick={() => setWizardAccountId(account.id)}>进入微信公众号验收向导</button>}{account.platformKey === "douyin" && <button className="text-button douyin-wizard-link" onClick={() => setDouyinWizardAccountId(account.id)}>进入抖音验收向导</button>}<label className="check-row"><input type="checkbox" disabled={isBrowserPlatform} checked={account.allowAutoPublish} onChange={(event) => void window.publisherAPI.accounts.update(account.id, { allowAutoPublish: event.target.checked }).then(load)} /><span>{isBrowserPlatform ? "浏览器平台首阶段仅允许人工最终确认" : "允许队列自动真实发布"}</span></label>{messages[account.id] && <div className="account-warning">{messages[account.id]}</div>}{account.pausedReason && <div className="account-warning">⚠ {account.pausedReason}</div>}</div>;
  })}</section></>;
}

function AccountsPageV02({ refresh }: { refresh: () => void }): JSX.Element {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [platforms, setPlatforms] = useState<Platform[]>([]);
  const [name, setName] = useState("");
  const [platformKey, setPlatformKey] = useState("test");
  const [credentials, setCredentials] = useState<Record<string, Record<string, string>>>({});
  const [credentialStatus, setCredentialStatus] = useState<Record<string, Awaited<ReturnType<typeof window.publisherAPI.accounts.credentialStatus>>>>({});
  const [loginSessions, setLoginSessions] = useState<Record<string, Awaited<ReturnType<typeof window.publisherAPI.accounts.beginLogin>>>>({});
  const [callbackUrls, setCallbackUrls] = useState<Record<string, string>>({});
  const [messages, setMessages] = useState<Record<string, string>>({});
  const load = (): void => { void Promise.all([window.publisherAPI.accounts.list(), window.publisherAPI.platforms.list()]).then(([nextAccounts, nextPlatforms]) => { setAccounts(nextAccounts); setPlatforms(nextPlatforms); }); };
  useEffect(load, [refresh]);
  const create = async (): Promise<void> => { if (!name.trim()) return; await window.publisherAPI.accounts.create({ platformKey, name }); setName(""); load(); refresh(); };
  const saveCredentials = async (account: Account): Promise<void> => {
    const values = Object.fromEntries(Object.entries(credentials[account.id] ?? {}).filter(([, value]) => value.trim()));
    if (Object.keys(values).length === 0) return;
    try {
      const status = await window.publisherAPI.accounts.setCredentials({ accountId: account.id, platformKey: account.platformKey, values });
      setCredentials((current) => ({ ...current, [account.id]: {} }));
      setCredentialStatus((current) => ({ ...current, [account.id]: { ...status, expired: false } }));
      setMessages((current) => ({ ...current, [account.id]: status.configured ? "所需凭据已加密保存" : "已加密保存，仍有必填项未配置" }));
    } catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "凭据保存失败" })); }
  };
  const beginLogin = async (account: Account): Promise<void> => {
    try {
      const session = await window.publisherAPI.accounts.beginLogin(account.id, account.platformKey);
      setLoginSessions((current) => ({ ...current, [account.id]: session }));
      setMessages((current) => ({ ...current, [account.id]: session.message ?? "请完成平台正常授权" }));
      load();
    } catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "授权启动失败" })); }
  };
  const completeLogin = async (account: Account): Promise<void> => {
    const callbackUrl = callbackUrls[account.id]?.trim();
    if (!callbackUrl) return;
    try {
      await window.publisherAPI.accounts.completeLogin(account.id, account.platformKey, callbackUrl);
      beginPostLoginHeartbeat(account.id, account.platformKey);
      setCallbackUrls((current) => ({ ...current, [account.id]: "" }));
      setMessages((current) => ({ ...current, [account.id]: "OAuth 授权已安全完成" }));
      load();
    } catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "OAuth 回调处理失败" })); }
  };
  const checkLogin = async (account: Account): Promise<void> => {
    try { await runCheckLoginWithHeartbeats(account.id, account.platformKey, () => window.publisherAPI.accounts.checkLogin(account.id, account.platformKey)); load(); }
    catch (error) { setMessages((current) => ({ ...current, [account.id]: error instanceof Error ? error.message : "登录检查失败" })); }
  };
  return <><PageTitle eyebrow="账号管理" title="全部账号" description="凭据按 Adapter manifest 渲染并由主进程安全存储；页面只回显配置状态。验证码和安全验证只允许用户在平台正常流程中完成。" /><div className="inline-create panel"><select value={platformKey} onChange={(event) => setPlatformKey(event.target.value)}>{platforms.map((platform) => <option value={platform.platformKey} key={platform.platformKey}>{platform.displayName}</option>)}</select><input placeholder="新增账号名称" value={name} onChange={(event) => setName(event.target.value)} /><button className="primary-button" onClick={() => void create()}>添加账号</button></div><section className="account-grid">{accounts.map((account) => {
    const platform = platforms.find((item) => item.platformKey === account.platformKey);
    const values = credentials[account.id] ?? {};
    const status = credentialStatus[account.id];
    const session = loginSessions[account.id];
    const fields = platform?.credentialSchema ?? [];
    return <div className="panel account-card" key={account.id}><div className="account-top"><div className="platform-avatar">{account.platformKey.slice(0, 1).toUpperCase()}</div><div><strong>{account.name}</strong><span>{account.platformKey}</span></div><button className={`toggle ${account.enabled ? "on" : ""}`} onClick={() => void window.publisherAPI.accounts.update(account.id, { enabled: !account.enabled }).then(load)}><span /></button></div><div className="account-meta"><div><span>登录状态</span><StatusPill status={account.loginStatus} /></div><div><span>今日发布</span><b>{account.todayPublishCount}</b></div><div><span>自动发布</span><b>{account.allowAutoPublish ? "已允许" : "人工确认"}</b></div></div>{fields.length > 0 && <div className="credential-box">{fields.map((field) => <label key={field.key}>{field.label}{status?.fields.find((item) => item.key === field.key)?.configured && <small>已配置</small>}<input type={field.type === "secret" ? "password" : "text"} value={values[field.key] ?? ""} placeholder={field.required ? "必填；保存后不回显" : "可选；保存后不回显"} onChange={(event) => setCredentials((current) => ({ ...current, [account.id]: { ...values, [field.key]: event.target.value } }))} /></label>)}<button className="secondary-button wide" onClick={() => void saveCredentials(account)}>保存到安全存储</button><button className="text-button" onClick={() => void window.publisherAPI.accounts.credentialStatus(account.id, account.platformKey).then((next) => setCredentialStatus((current) => ({ ...current, [account.id]: next })))}>刷新配置状态</button>{platform?.adapterStatus !== "not_implemented" && <div className="row-actions"><button className="mini-button" onClick={() => void beginLogin(account)}>开始官方登录 / OAuth</button><button className="mini-button" onClick={() => void checkLogin(account)}>检查登录</button></div>}{session?.authorizationUrl && <><small>官方授权页已在系统浏览器中打开。</small><label>粘贴授权后的完整回调 URL<input value={callbackUrls[account.id] ?? ""} onChange={(event) => setCallbackUrls((current) => ({ ...current, [account.id]: event.target.value }))} /></label><button className="secondary-button wide" onClick={() => void completeLogin(account)}>完成 OAuth</button></>}</div>}<label className="check-row"><input type="checkbox" checked={account.allowAutoPublish} onChange={(event) => void window.publisherAPI.accounts.update(account.id, { allowAutoPublish: event.target.checked }).then(load)} /><span>允许队列自动真实发布</span></label>{messages[account.id] && <div className="account-warning">{messages[account.id]}</div>}{account.pausedReason && <div className="account-warning">⚠ {account.pausedReason}</div>}</div>;
  })}</section></>;
}

function PlatformsPageV02(): JSX.Element {
  const [platforms, setPlatforms] = useState<Platform[]>([]);
  useEffect(() => { void window.publisherAPI.platforms.list().then(setPlatforms); }, []);
  return <><PageTitle eyebrow="账号管理 / 平台管理" title="平台能力目录" description="能力状态来自调研矩阵与 Adapter 注册状态；未验证的平台不会被伪装成可发布。" /><section className="platform-grid">{platforms.map((platform, index) => <div className="platform-card" key={platform.platformKey}><div className={`platform-logo logo-${index % 6}`}>{platform.platformKey === "test" ? "T" : platform.displayName.slice(0, 1)}</div><strong>{platform.displayName}</strong><span>{platform.category}</span><b>接入方式：{integrationModeLabel(platform)}</b><StatusPill status={platform.adapterStatus} /><small>验收：{platform.verificationStatus} · 调研：{platform.researchStatus} · 健康：{platform.healthStatus}</small></div>)}</section></>;
}

function QueuePageV02({ refresh }: { refresh: () => void }): JSX.Element {
  const [jobs, setJobs] = useState<PublishJob[]>([]);
  const [running, setRunning] = useState<string | null>(null);
  const load = (): void => { void window.publisherAPI.jobs.list().then(setJobs); };
  useEffect(load, [refresh]);
  const run = async (id: string): Promise<void> => { setRunning(id); await window.publisherAPI.jobs.run(id); setRunning(null); load(); refresh(); };
  const confirmAndRun = async (id: string): Promise<void> => { setRunning(id); await window.publisherAPI.jobs.confirm(id, false); await window.publisherAPI.jobs.run(id); setRunning(null); load(); refresh(); };
  return <><PageTitle eyebrow="发布中心" title="发布队列" description="默认先 dry-run；真实发布必须在队列中明确确认，自动发布还需要账号级授权。" action={<button className="secondary-button" onClick={() => void window.publisherAPI.jobs.recover().then(load)}>恢复未完成任务</button>} /><section className="panel table-panel"><div className="table-summary"><span>共 {jobs.length} 个任务</span><div className="legend"><StatusPill status="Success" /><StatusPill status="Retry" /><StatusPill status="NeedsUserAction" /></div></div>{jobs.length === 0 ? <EmptyState title="队列为空" description="创建发布计划并生成今天任务。" /> : <div className="data-table"><div className="table-head queue-head"><span>任务</span><span>平台 / 账号</span><span>计划时间</span><span>尝试次数</span><span>状态</span><span>操作</span></div>{jobs.map((job) => <div className="table-row queue-row" key={job.id}><div><strong>{job.id.slice(0, 12)}</strong><span>文章 {job.articleId.slice(0, 8)}</span></div><span>{job.platformKey}<br /><small>{job.accountId.slice(0, 8)}</small></span><span>{new Date(job.scheduledAt).toLocaleString("zh-CN")}</span><span>{job.attemptCount} / {job.maxAttempts}</span><div><StatusPill status={job.status} /><small>{job.dryRun ? "dry-run" : "真实发布"}</small></div><div className="row-actions">{["Pending", "Scheduled", "Retry", "NeedsUserAction"].includes(job.status) && <><button className="mini-button" disabled={running === job.id} onClick={() => void run(job.id)}>预演</button><button className="mini-button danger-mini" disabled={running === job.id} onClick={() => void confirmAndRun(job.id)}>确认真实发布</button></>}{job.status === "Failed" && <button className="mini-button" onClick={() => void window.publisherAPI.jobs.retry(job.id).then(load)}>重试</button>}</div></div>)}</div>}</section></>;
}

function SettingsPageV02(): JSX.Element {
  const [settings, setSettings] = useState<Record<string, unknown>>({});
  const [secret, setSecret] = useState("");
  const [imageSecret, setImageSecret] = useState("");
  const [message, setMessage] = useState("");
  const [profiles, setProfiles] = useState<Awaited<ReturnType<typeof window.publisherAPI.ai.profiles>>>([]);
  useEffect(() => { void Promise.all([window.publisherAPI.settings.get(), window.publisherAPI.ai.profiles()]).then(([nextSettings, nextProfiles]) => { setSettings(nextSettings); setProfiles(nextProfiles); }); }, []);
  const save = (key: string, value: string | number | boolean): void => { setSettings({ ...settings, [key]: value }); void window.publisherAPI.settings.update(key, value); };
  const test = async (): Promise<void> => { const result = await window.publisherAPI.settings.testAi(); setMessage(result.message); };
  const saveSecret = async (kind: "apiKey" | "imageApiKey", value: string): Promise<void> => { if (!value.trim()) return; await window.publisherAPI.settings.setSecret(kind, value); setSettings((current) => ({ ...current, [kind === "apiKey" ? "apiKeyConfigured" : "imageApiKeyConfigured"]: true })); if (kind === "apiKey") setSecret(""); else setImageSecret(""); };
  const createProfile = async (): Promise<void> => { const profile = await window.publisherAPI.ai.upsertProfile({ name: `AI Profile ${profiles.length + 1}`, provider: String(settings.provider ?? "mock"), baseUrl: String(settings.baseUrl ?? "https://api.openai.com/v1"), model: String(settings.model ?? "gpt-4o-mini"), credentialRef: "ai:apiKey", temperature: Number(settings.temperature ?? 0.7), maxOutputTokens: Number(settings.maxOutputTokens ?? 3000), timeoutMs: Number(settings.timeout ?? 30000), retryCount: Number(settings.retry ?? 2), concurrency: Number(settings.concurrency ?? 2), enabled: true, isDefault: profiles.length === 0, isFallback: false }); setProfiles((items) => [...items, profile]); if (profiles.length === 0) save("defaultAiProfileId", profile.id); };
  return <><PageTitle eyebrow="系统设置 / AI 设置" title="AI 与图片 Provider" description="API Key 仅在 Electron 主进程通过系统安全存储加密保存；Renderer 只能看到是否已配置。" action={<button className="secondary-button" onClick={() => void test()}>测试 AI 连接</button>} />{message && <div className="notice success">{message}</div>}<div className="settings-layout"><section className="panel form-panel"><div className="panel-heading"><div><h3>文本 AI</h3><span>OpenAI-compatible Chat Completions</span></div></div><label>Provider<input value={String(settings.provider ?? "mock")} onChange={(event) => save("provider", event.target.value)} placeholder="mock 或 openai-compatible" /></label><label>Base URL<input value={String(settings.baseUrl ?? "https://api.openai.com/v1")} onChange={(event) => save("baseUrl", event.target.value)} /></label><label>Model<input value={String(settings.model ?? "gpt-4o-mini")} onChange={(event) => save("model", event.target.value)} /></label><label>API Key<input type="password" value={secret} onChange={(event) => setSecret(event.target.value)} placeholder={settings.apiKeyConfigured ? "已配置，输入新 Key 可替换" : "仅本次输入"} /><button className="secondary-button" onClick={() => void saveSecret("apiKey", secret)}>保存到安全存储</button></label></section><section className="panel form-panel"><div className="panel-heading"><div><h3>生成参数</h3><span>有限重试与可审计用量</span></div></div><label>Temperature<input type="number" min="0" max="2" step="0.1" value={Number(settings.temperature ?? 0.7)} onChange={(event) => save("temperature", Number(event.target.value))} /></label><label>最大输出 tokens<input type="number" min="128" max="32000" value={Number(settings.maxOutputTokens ?? 3000)} onChange={(event) => save("maxOutputTokens", Number(event.target.value))} /></label><label>请求超时（毫秒）<input type="number" value={Number(settings.timeout ?? 30000)} onChange={(event) => save("timeout", Number(event.target.value))} /></label><label>失败重试次数<input type="number" min="0" max="5" value={Number(settings.retry ?? 2)} onChange={(event) => save("retry", Number(event.target.value))} /></label><label>批量并发<input type="number" min="1" max="20" value={Number(settings.concurrency ?? 2)} onChange={(event) => save("concurrency", Number(event.target.value))} /></label></section><section className="panel form-panel"><div className="panel-heading"><div><h3>图片 Provider</h3><span>失败自动回退到模板封面</span></div></div><label>Provider<input value={String(settings.imageProvider ?? "mock")} onChange={(event) => save("imageProvider", event.target.value)} /></label><label>Model<input value={String(settings.imageModel ?? "gpt-image-1")} onChange={(event) => save("imageModel", event.target.value)} /></label><label>Image API Key<input type="password" value={imageSecret} onChange={(event) => setImageSecret(event.target.value)} placeholder={settings.imageApiKeyConfigured ? "已配置，输入新 Key 可替换" : "仅本次输入"} /><button className="secondary-button" onClick={() => void saveSecret("imageApiKey", imageSecret)}>保存到安全存储</button></label><div className="hint-box">未配置真实图片 Key 时仍可用模板封面，生成流程不会被阻塞。</div></section><section className="panel form-panel"><div className="panel-heading"><div><h3>AI Provider Profiles</h3><span>可保存默认、备用、低成本或高质量配置</span></div><button className="secondary-button" onClick={() => void createProfile()}>保存当前为 Profile</button></div>{profiles.length === 0 ? <EmptyState compact title="尚未保存 Profile" description="保存后可在主进程选择默认或备用模型。" /> : <div className="log-list">{profiles.map((profile) => <div className="log-row" key={profile.id}><strong>{profile.name}</strong><span>{profile.provider} / {profile.model}</span><span>{profile.isDefault ? "默认" : profile.isFallback ? "备用" : "已保存"}</span><button className="mini-button" onClick={() => void window.publisherAPI.ai.deleteProfile(profile.id).then(() => setProfiles((items) => items.filter((item) => item.id !== profile.id)))}>删除</button></div>)}</div>}</section></div></>;
}

function DashboardPageV02({ refreshKey, onNavigate }: { refreshKey: number; onNavigate: (route: Route) => void }): JSX.Element {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [notifications, setNotifications] = useState<{ id: string; level: string; title: string; message: string; read: boolean }[]>([]);
  useEffect(() => { void Promise.all([window.publisherAPI.dashboard.get(), window.publisherAPI.notifications.list(5)]).then(([nextStats, nextNotifications]) => { setStats(nextStats); setNotifications(nextNotifications); }); }, [refreshKey]);
  const value = stats ?? { publishedToday: 0, pendingJobs: 0, failedJobs: 0, runningJobs: 0, totalAccounts: 0, onlineAccounts: 0, expiredAccounts: 0, availableArticles: 0, generatedToday: 0, estimatedStockDays: 0, activeAiTasks: 0, benchmarkArticles: 0, productionArticles: 0 };
  return <><PageTitle eyebrow="运营总览" title="内容与发布状态" description="真实发布、dry-run、AI 用量和账号暂停状态均来自本地审计数据。" action={<button className="primary-button" onClick={() => onNavigate("batch")}>＋ 创建内容</button>} /><div className="stat-grid"><StatCard label="今日记录" value={value.publishedToday} hint="成功 PublishRecord" icon="↗" /><StatCard label="待人工确认" value={value.pendingJobs} hint="持久化队列" tone="purple" icon="◷" /><StatCard label="可用文章" value={value.availableArticles} hint={`正式 ${value.productionArticles} · Benchmark ${value.benchmarkArticles}（不计入）`} tone="green" icon="▤" /><StatCard label="在线账号" value={`${value.onlineAccounts} / ${value.totalAccounts}`} hint={`${value.expiredAccounts} 个需处理`} tone="orange" icon="◎" /></div><div className="dashboard-grid"><section className="panel health-panel"><div className="panel-heading"><div><h3>V0.2 能力状态</h3><span>官方 API 优先，未验证平台保持关闭</span></div><span className="status-chip success">● 本地可用</span></div><div className="health-row"><span>SQLite migration</span><b>0001 已应用</b></div><div className="health-row"><span>Mock / OpenAI-compatible AI</span><b>可切换</b></div><div className="health-row"><span>模板 / 真实图片 Provider</span><b>带 fallback</b></div><div className="health-row"><span>微信公众号 Adapter</span><b>草稿 dry-run + 正式分支</b></div><div className="stock-alert"><span>♢</span><div><strong>{value.availableArticles < 10 ? "内容库存偏低" : "内容库存充足"}</strong><p>{value.availableArticles < 10 ? "前往批量生成补充文章。" : "当前库存可以支持持续排期。"}</p></div></div></section><section className="panel table-panel"><div className="panel-heading"><div><h3>最近通知</h3><span>登录失效、人工验证、失败与 dry-run 结果</span></div></div>{notifications.length === 0 ? <EmptyState compact title="暂无通知" description="系统事件会显示在这里。" /> : <div className="log-list">{notifications.map((item) => <div className="log-row" key={item.id}><b className={item.level}>{item.read ? "已读" : "未读"}</b><strong>{item.title}</strong><span>{item.message}</span></div>)}</div>}</section></div></>;
}

function formatAccountDate(value: string | null | undefined): string { if (!value) return "暂无"; const timestamp = Date.parse(value); return Number.isFinite(timestamp) ? new Date(timestamp).toLocaleString("zh-CN", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }) : "无效时间"; }
function integrationModeLabel(platform: Platform | null): string { if (!platform) return "未知"; if (platform.integrationMode) return platform.integrationMode === "BrowserAutomation" ? "浏览器自动化" : platform.integrationMode === "SemiAuto" ? "半自动" : platform.integrationMode === "OAuth" ? "OAuth" : platform.integrationMode === "API" ? "官方 API" : platform.integrationMode === "Blocked" ? "不可接入" : "人工"; if (platform.transport === "browser") return "浏览器自动化"; if (platform.transport === "semi_auto") return "半自动"; if (platform.authStrategy === "OAuth2" || platform.authStrategy === "OAuth2PKCE") return "OAuth"; if (platform.transport === "official_api" || platform.transport === "official_sdk") return "官方 API"; return "人工"; }
function StatusPill({ status }: { status: string }): JSX.Element { const map: Record<string, string> = { Success: "success", available: "success", logged_in: "success", ready: "success", Connected: "success", Authorized: "success", DryRunPassed: "success", PublishPassed: "success", 已配置: "success", 启用: "success", Retry: "warning", Pending: "warning", Scheduled: "warning", NotTested: "muted", 未配置: "warning", unknown: "muted", Unknown: "muted", not_implemented: "muted", NotConnected: "muted", 停用: "muted", Failed: "danger", expired: "danger", Expired: "danger", Revoked: "danger", Paused: "danger", NeedsUserAction: "purple", NeedsLogin: "purple", NeedsReauth: "purple", Connecting: "purple", Partial: "warning", Running: "purple", generating: "purple", NeedsRewrite: "warning", archived: "muted" }; const labels: Record<string, string> = { logged_in: "正常", not_implemented: "未接入", needs_user_action: "待用户授权", logged_out: "未授权", expired: "已过期", Connected: "已连接", NotConnected: "未连接", Connecting: "连接中", Expired: "已过期", NeedsLogin: "需要重新登录", NeedsReauth: "需要重新登录", Error: "错误", Authorized: "已授权", Partial: "授权不完整", Revoked: "已撤销", NotAuthorized: "未授权", Unknown: "未知", DryRunPassed: "Dry Run 已通过", PublishPassed: "发布已验收", NotTested: "未测试", 已配置: "已配置", 未配置: "未配置", 启用: "启用", 停用: "停用", NeedsRewrite: "NeedsRewrite", archived: "Archived" }; return <span className={`status-pill ${map[status] ?? "muted"}`}>{labels[status] ?? status}</span>; }
function EmptyState({ title, description, action, compact = false }: { title: string; description: string; action?: React.ReactNode; compact?: boolean }): JSX.Element { return <div className={`empty-state ${compact ? "compact" : ""}`}><div className="empty-icon">{compact ? "○" : "▱"}</div><strong>{title}</strong><p>{description}</p>{action}</div>; }
